#include <Arduino.h>
TaskHandle_t receiver = nullptr;
void receiverTask(void*) { for (;;) { ulTaskNotifyTake(pdTRUE, portMAX_DELAY); Serial.println("one event"); } }
void setup() { Serial.begin(115200); if (xTaskCreate(receiverTask, "receiver", 2048, nullptr, 1, &receiver) != pdPASS) { receiver = nullptr; Serial.println("receiver task creation failed"); } }
void loop() { if (receiver) xTaskNotifyGive(receiver); vTaskDelay(pdMS_TO_TICKS(1000)); }

#include <Arduino.h>
TaskHandle_t workerHandle = nullptr;
void worker(void*) { for (;;) { ulTaskNotifyTake(pdTRUE, portMAX_DELAY); Serial.println("event received"); } }
void setup() { Serial.begin(115200); xTaskCreate(worker, "worker", 2048, nullptr, 1, &workerHandle); }
void loop() { if (workerHandle) xTaskNotifyGive(workerHandle); vTaskDelay(pdMS_TO_TICKS(1000)); }
